// Серверные проверки TAQO (прежнее имя — Tenderflow IL): запросы к Supabase REST (PostgREST) от имени роли.
// Токен — из localStorage сохранённой сессии (sb-*-auth-token), anon key и адрес Supabase — из бандла сайта.
// Паролей нет. Только чтение и попытки записи, которые сервер должен отклонить; DELETE не используется.
import { Page, APIResponse, expect } from '@playwright/test';

export type SbSession = {
  page: Page;
  url: string;      // https://<ref>.supabase.co
  apiKey: string;   // anon / publishable key из бандла
  token: string;    // access_token пользователя
  userId: string;
};

/** Адрес Supabase и anon key из JS-бандла сайта (скрипты страницы, открытой в page). */
async function bundleConfig(page: Page): Promise<{ url: string; apiKey: string }> {
  const srcs: string[] = await page.evaluate(() =>
    Array.from(document.querySelectorAll('script[src]')).map((s) => (s as HTMLScriptElement).src),
  );
  for (const src of srcs) {
    const js = await (await page.request.get(src)).text();
    const url = js.match(/https:\/\/[a-z0-9]+\.supabase\.co/)?.[0];
    if (!url) continue;
    // Ключ: JWT с role=anon или новый publishable-ключ.
    const jwts = js.match(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g) ?? [];
    const anon = jwts.find((t) => {
      try {
        return JSON.parse(Buffer.from(t.split('.')[1], 'base64url').toString()).role === 'anon';
      } catch {
        return false;
      }
    });
    const apiKey = anon ?? js.match(/sb_publishable_[A-Za-z0-9_-]+/)?.[0];
    if (apiKey) return { url, apiKey };
  }
  throw new Error('Не найден адрес Supabase / anon key в бандле сайта');
}

/**
 * Сессия Supabase для страницы, открытой с storageState роли.
 * Открывает «/» (supabase-js обновляет истёкший токен) и читает sb-*-auth-token из localStorage.
 */
export async function sbSession(page: Page): Promise<SbSession> {
  await page.goto('/');
  await expect(page.getByRole('navigation', { name: 'ניווט ראשי' })).toBeVisible();
  return sbSessionHere(page);
}

/**
 * То же, что sbSession, но без перехода на «/»: для страницы, которая уже открыта (например, мастер /onboarding
 * без главного меню). Токен читается из localStorage текущей страницы.
 */
export async function sbSessionHere(page: Page): Promise<SbSession> {
  const { url, apiKey } = await bundleConfig(page);
  const ref = new URL(url).hostname.split('.')[0];
  const raw = await page.evaluate((key) => localStorage.getItem(key), `sb-${ref}-auth-token`);
  if (!raw) throw new Error(`Нет sb-${ref}-auth-token в localStorage — сессия роли устарела, запусти npm run qa-login`);
  const parsed = JSON.parse(raw);
  const s = parsed.currentSession ?? parsed;
  if (!s?.access_token || !s?.user?.id) throw new Error('В sb-*-auth-token нет access_token / user.id');
  return { page, url, apiKey, token: s.access_token, userId: s.user.id };
}

const headers = (s: SbSession, prefer?: string) => ({
  apikey: s.apiKey,
  Authorization: `Bearer ${s.token}`,
  'Content-Type': 'application/json',
  ...(prefer ? { Prefer: prefer } : {}),
});

/** GET /rest/v1/<path> → массив строк (ожидается 200). */
export async function sbSelect<T = Record<string, unknown>>(s: SbSession, path: string): Promise<T[]> {
  const res = await s.page.request.get(`${s.url}/rest/v1/${path}`, { headers: headers(s) });
  expect(res.status(), `GET ${path}: ${await res.text()}`).toBe(200);
  return res.json();
}

/** PATCH /rest/v1/<path> с return=representation — в ответе изменённые строки. */
export async function sbPatch(s: SbSession, path: string, body: Record<string, unknown>): Promise<APIResponse> {
  return s.page.request.patch(`${s.url}/rest/v1/${path}`, { headers: headers(s, 'return=representation'), data: body });
}

/** POST /rest/v1/<table> с return=minimal (без зависимости от права на чтение новой строки). */
export async function sbInsert(s: SbSession, table: string, body: Record<string, unknown>): Promise<APIResponse> {
  return s.page.request.post(`${s.url}/rest/v1/${table}`, { headers: headers(s, 'return=minimal'), data: body });
}

/** company_id компании, в которой состоит пользователь сессии. */
export async function myCompanyId(s: SbSession): Promise<string> {
  const rows = await sbSelect<{ company_id: string }>(s, `company_members?select=company_id&user_id=eq.${s.userId}`);
  expect(rows, 'пользователь должен состоять ровно в одной компании').toHaveLength(1);
  return rows[0].company_id;
}
